# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 187-210. AYETLERİN KONU VE ANLAM ÇERÇEVESİ</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Ayetler 187-195: İbadet ve Adalet</text>\n  <text x="40" y="100" font-size="11" fill="#334155">• 187. Ayet: Ramazan orucunun</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  gece-gündüz sınırları (imsak-iftar)</text>\n  <text x="40" y="132" font-size="11" fill="#334155">  ve mescitlerde itikâf ibadeti.</text>\n  <text x="40" y="154" font-size="11" fill="#334155">• 188. Ayet: Malları batıl yollarla</text>\n  <text x="40" y="170" font-size="11" fill="#334155">  ve rüşvetle yememe emri.</text>\n  <text x="40" y="192" font-size="11" fill="#334155">• 189-195: Hilaller ve infak bilinci.</text>\n  <text x="130" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Helal Kazanç ve İnfak</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Ayetler 196-203: Hac ve Umre</text>\n  <text x="260" y="100" font-size="11" fill="#334155">• 196. Ayet: "Haccı ve umreyi</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  Allah için tam yapın" emri.</text>\n  <text x="260" y="138" font-size="11" fill="#334155">• 197. Ayet: Hacda kötü söz, günah</text>\n  <text x="260" y="154" font-size="11" fill="#334155">  ve kavga yasağı; en hayırlı azık</text>\n  <text x="260" y="170" font-size="11" fill="#334155">  takvadır (وَخَيْرَ الزَّادِ التَّقْوَى).</text>\n  <text x="260" y="192" font-size="11" fill="#334155">• 198-203: Arafat, Meş\'ar-i Haram.</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Takva Azığı ve Hac Ahlakı</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Ayetler 201-210: Rabbenâ ve Barış</text>\n  <text x="480" y="100" font-size="11" fill="#334155">• 201. Ayet: "Rabbenâ âtinâ fi\'d-dünyâ</text>\n  <text x="480" y="116" font-size="11" fill="#334155">  haseneten ve fi\'l-âhirati haseneh..."</text>\n  <text x="480" y="138" font-size="11" fill="#334155">• 204-207: Sözüyle davranışı bir</text>\n  <text x="480" y="154" font-size="11" fill="#334155">  olan samimi müminlerin özelliği.</text>\n  <text x="480" y="176" font-size="11" fill="#334155">• 208. Ayet: "Ey iman edenler!</text>\n  <text x="480" y="192" font-size="11" fill="#334155">  Hep birlikte barışa (İslam\'a) girin."</text>\n  <text x="570" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Dünya ve Ahiret İyiliği (Hasene)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 187-210. AYETLERDE SAKİN MİM VE İDGAM UYGULAMALARI</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Sakin Mimin Hâlleri Örnekleri (KK.7.2.2-3)</text>\n  <text x="44" y="102" font-size="11.5" font-weight="bold" fill="#1e40af">1. İhfa-i Şefevî (مْ + ب):</text>\n  <text x="52" y="120" font-size="11" fill="#334155">• أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ (Bakara, 188)</text>\n  <text x="44" y="146" font-size="11.5" font-weight="bold" fill="#15803d">2. İdgam-ı Misleyn Meal-Gunne (مْ + م):</text>\n  <text x="52" y="164" font-size="11" fill="#334155">• لَكُمْ مَا كَسَبْتُمْ / أَنْتُمْ مُعْرِضُونَ (Bakara, 200)</text>\n  <text x="44" y="190" font-size="11.5" font-weight="bold" fill="#b45309">3. İzhar-ı Şefevî (مْ + Diğer 26 Harf):</text>\n  <text x="52" y="208" font-size="11" fill="#334155">• أَحَلَّ اللّٰهُ لَكُمْ لَيْلَةَ الصِّيَامِ / عَلَيْكُمْ فِيهِ</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Diğer Tecvit Kuralları ve Vakıf İşaretleri</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">• İdgam-ı Misleyn Meal-Gunne (نْ + ن):</text>\n  <text x="388" y="118" font-size="11" fill="#991b1b">فَمِنَ النَّاسِ مَنْ يَقُولُ (İdgam-ı Maal-Gunne)</text>\n  <text x="378" y="142" font-size="11.5" fill="#334155">• İdgam-ı Misleyn Bilâ-Gunne (Diğer harfler):</text>\n  <text x="388" y="160" font-size="11" fill="#991b1b">اضْرِبْ بِعَصَاكَ / قَدْ دَخَلُوا (Gunnesiz birleştirme)</text>\n  <text x="378" y="184" font-size="11.5" fill="#334155">• Lafzatullah (اللّٰه) ve Kalkale (ق ط ب ج د):</text>\n  <text x="388" y="202" font-size="11" fill="#991b1b">وَاتَّقُوا اللّٰهَ (kalın) · بِالّٰلهِ (ince) · الْحَجُّ أَشْهُرٌ</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BAKARA SURESİ 201. AYET (RABBENÂ ÂTİNÂ DUASI) VE YÜZÜNDEN OKUMA</text>\n  <rect x="28" y="48" width="644" height="90" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="76" text-anchor="middle" font-size="15" font-weight="bold" fill="#166534">رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Okunuşu: "Rabbenâ âtinâ fi\'d-dünyâ haseneten ve fi\'l-âhirati haseneten ve kınâ azâbe\'n-nâr."</text>\n  <text x="350" y="124" text-anchor="middle" font-size="11.5" fill="#334155">Anlamı: "Rabbimiz! Bize dünyada da iyilik (hasene) ver, ahirette de iyilik ver ve bizi ateş azabından koru." (Bakara, 201)</text>\n  <rect x="28" y="150" width="310" height="90" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Yüzünden Okuma İlkeleri (Tertil)</text>\n  <text x="44" y="194" font-size="11" fill="#334155">• Peltek harfleri (ث، ذ، ظ) ve boğaz harflerini (ح، ع)</text>\n  <text x="44" y="210" font-size="11" fill="#334155">  kendi mahreçlerinden doğru telaffuz etmek.</text>\n  <text x="44" y="226" font-size="11" fill="#334155">• Med (uzatma) ve gunne sürelerini korumak.</text>\n  <rect x="362" y="150" width="310" height="90" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">201. Ayetteki Tecvit Örnekleri</text>\n  <text x="378" y="194" font-size="11" fill="#334155">• رَبَّنَا آتِنَا → Medd-i Munfasıl (4 elif uzatma)</text>\n  <text x="378" y="210" font-size="11" fill="#334155">• حَسَنَةً وَفِي → İdgam-ı Maal-Gunne (tenvin + و)</text>\n  <text x="378" y="226" font-size="11" fill="#334155">• النَّارِ (Durulduğunda) → Medd-i Ârız + Gunne</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
